  "q": "자동차관리법상 운행정지명령 위반 운행과 의무보험 미가입 운행이 함께 문제된 사안에 관한 판례(대법원 2023. 4. 27. 선고 2020도17883 판결)의 태도로 옳은 것은?",
  "opts": [
   "운행정지명령이 위법하더라도 당연무효가 아닌 이상 그 명령을 위반한 운행에 대해서는 자동차관리법 위반죄가 성립한다.",
   "자동차 소유자로부터 운행을 위탁받은 사용자가 운행한 경우라도 정당한 사유가 없으면 운행정지명령의 요건을 갖춘다.",
   "의무보험 미가입 운행으로 인한 자배법 위반죄와 자동차관리법 위반죄는 실체적 경합 관계에 있다.",
   "두 죄는 하나의 운행행위로 저질러진 것이므로 보호법익이 같아 자배법 위반죄 하나만 성립한다."
  ],
  "ans": 2,
  "exp": "대법원은 자동차관리법상 운행정지명령은 소유자나 그로부터 위탁받은 사용자가 아닌 자가 정당한 사유 없이 운행한 경우에만 적법하게 내릴 수 있다고 보고, 위탁받은 사용자에게 내린 명령은 적법요건을 갖추지 못하였으므로 당연무효가 아니더라도 위반죄가 성립하지 않는다고 하였다. 또한 자배법 위반죄(의무보험 미가입 운행)와 자동차관리법 위반죄는 구성요건과 보호법익이 달라 상상적 경합이 아니라 실체적 경합 관계라고 하였다.",
