   "대차비용은 원칙적으로 사고 당시 대차시장에서 형성된 가액을 기준으로 산정한다.",
   "피해차량보다 연식이 새로운 차량을 대차한 경우 그 차이를 고려하여 대차비용을 감액할 수 있다."
