  "q": "화재로 손해를 입은 피보험자가 두 보험자와 중복보험 관계에 있는데 그중 한 보험자가 보험금을 지급하고 화재에 책임이 있는 가해자에게 보험자대위를 주장한 사안에서, 판례(대법원 2026. 5. 14. 선고 2025다220815 판결)의 태도로 옳은 것은?",
