  "exp": "대법원은 약관은 평균적 고객의 이해가능성을 기준으로 해석하여야 하고, 관리대행 손해 면책 조항은 순수한 관리대행에만 적용되며, 관리대행이 중개행위와 결합하여 공인중개사법 제30조의 책임이 성립하는 경우에는 적용되지 않는다고 보아 원심을 파기하였다. 뜻이 명백하지 않은 약관은 고객에게 유리하게 해석한다(약관규제법 제5조 제2항).",
