   "백색실선은 '통행금지를 내용으로 하는 안전표지'가 아니어서 종합보험(공제) 가입 시 처벌 특례가 적용될 수 있다.",
   "백색실선 침범은 신호위반에 해당하므로 종합보험(공제)에 가입하였더라도 피해자의 의사와 관계없이 공소를 제기할 수 있다.",
   "이 판결은 백색실선 침범을 처벌 특례 배제사유로 본 종전 판례를 그대로 유지하였다."
