  "exp": "전원합의체는 진로변경제한선인 백색실선이 교통사고처리 특례법 제3조 제2항 단서 제1호의 '통행금지를 내용으로 하는 안전표지'에 해당하지 않는다고 보아, 백색실선 침범 사고에도 반의사불벌과 종합보험 가입 특례가 적용된다고 하였다. 이와 달리 본 대법원 2004도1196 판결은 변경되었다.",
  "ref": "대법원 2024. 6. 20. 선고 2022도12175 전원합의체 판결, 교통사고처리 특례법 제3조 제2항, 제4조",
